<?php
namespace App\Domain\CaseStudies; use App\Domain\PublicChrome\{PublicAssetPath,PublicLink}; use App\Models\CaseStudy; use Illuminate\Support\Facades\Cache; use Throwable; final class CaseStudyViewData { public function published(string $slug):?array{try{$x=CaseStudy::publiclyVisible()->where('slug',$slug)->first();if(!$x){return null;}return Cache::remember('public.case-studies.v1.'.$x->id.'.'.CaseStudyCache::version($x->id),now()->addMinutes(15),fn()=>$this->transform($this->load($x),false));}catch(Throwable){return null;}} public function preview(CaseStudy $x):array{return $this->transform($this->load($x),true);} private function load(CaseStudy $x):CaseStudy{return $x->load(['client','testimonial','metrics'=>fn($q)=>$q->where('is_active',true)->limit(8),'highlights'=>fn($q)=>$q->where('is_active',true)->limit(12),'relatedSolutions'=>fn($q)=>$q->publiclyVisible()->limit(8),'relatedProducts'=>fn($q)=>$q->publiclyVisible()->limit(8),'relatedIndustries'=>fn($q)=>$q->publiclyVisible()->limit(8),'relatedCapabilities'=>fn($q)=>$q->publiclyVisible()->limit(8),'relatedPages'=>fn($q)=>$q->publiclyVisible()->limit(6)]);} private function transform(CaseStudy $x,bool $preview):array{return ['title'=>$x->title,'slug'=>$x->slug,'eyebrow'=>$x->eyebrow,'description'=>$x->short_description,'challenge'=>$x->challenge,'solution'=>$x->solution,'outcome'=>$x->outcome,'image'=>PublicAssetPath::isSafe($x->featured_image_path)?$x->featured_image_path:null,'image_alt'=>$x->featured_image_alt,'client'=>$x->client?->isPubliclyVisible()?$x->client->name:null,'testimonial'=>$x->testimonial?->isPubliclyVisible()?['quote'=>$x->testimonial->quote,'person'=>$x->testimonial->person_name]:null,'metrics'=>$x->metrics->map->only(['label','value','prefix','suffix','description'])->all(),'highlights'=>$x->highlights->map->only(['title','description','icon'])->all(),'cta'=>PublicLink::isSafeUrl($x->primary_cta_url)?['label'=>$x->primary_cta_label,'url'=>$x->primary_cta_url]:null,'meta_title'=>$x->meta_title?:$x->title,'meta_description'=>$x->meta_description?:$x->short_description,'canonical_url'=>$x->canonical_url,'robots'=>$preview?'noindex, nofollow':(($x->robots_index?'index':'noindex').', '.($x->robots_follow?'follow':'nofollow'))];} }
